add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_gateways_only_on_order_pay' );

function perfectpixel_gateways_only_on_order_pay( $gateways ) {
	if ( is_admin() || is_wc_endpoint_url( 'order-pay' ) ) {
		return $gateways;
	}
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{order_pay_only_gateways}}' ) ) ) as $id ) {
		unset( $gateways[ $id ] );
	}
	return $gateways;
}
